def attach_data(task,topic):
 task['stimulus_specification']=DATA[topic]
 task['stimulus_specification']['dataset_id']='DATA-'+topic
 task['stimulus_specification']['data_provenance']='Original synthetic teaching data; not experimental measurements or official paper data.'
 task['answer_tolerance_policy']='Use stated tolerances for visual readings; exact arithmetic uses unrounded values. Accept correct follow-through from an allowed reading, without double penalising it.'
 if topic=='4':task['parts'][2]['credit_requirement']='Calculate the titre AND amount of HCl: final minus initial = 25.00 cm³ (1); convert to 0.02500 dm³ (1); n=cV=0.00250 mol (1).'
 if topic=='9':
  task['parts'][0]['command_word']='Plan'
  task['parts'][1]['credit_requirement']='Calculate magnesium average gas-production rate over 0–30 s: ΔV/Δt (1), 30/30=1.00 cm³/s (1).'
 if topic=='8':task['stimulus_specification']['candidate_ions']={'cations':['Cu²⁺','Fe²⁺','Fe³⁺'],'anions':['Cl⁻','Br⁻','I⁻']}
 if topic=='5':
  task['parts'][-1]['command_word']='Plan';task['parts'][-1]['mark_tariff']=6
  task['parts'][-1]['credit_requirement']='Plan the electrode comparison: name carbon/copper anodes (1), same CuSO4 concentration and volume (1), same current and time (1), measure clean dry electrode masses before/after (1), collect/test anode gas (1), compare mass changes and products to conclude the effect of electrode material (1).'
 return task
